// Package: com.javatodev.finance.configuration.filter
// Class: ApiRequestContextHolder
// Annotations: Slf4j

@Slf4j
public final class ApiRequestContextHolder {

    private ApiRequestContextHolder() {
    }

    private static final ThreadLocal<ApiRequestContext> contextHolder = new ThreadLocal<>();

    public static void clearContext() {
        contextHolder.remove();
    }

    public static ApiRequestContext getContext() {

        ApiRequestContext ctx = contextHolder.get();

        if (ctx == null) {
            ctx = new ApiRequestContext();
            contextHolder.set(ctx);
            log.debug("getContext() : new APIRequestContext created..!");
        }

        return ctx;
    }

}

// File: internet-banking-concept-microservices-main/internet-banking-utility-payment-service/src/main/java/com/javatodev/finance/configuration/filter/AppAuthUserFilter.java
// Package: com.javatodev.finance.configuration.filter
// Class: AppAuthUserFilter
// Annotations: Slf4j

@Slf4j
public class AppAuthUserFilter implements Filter {

    private static final String HTTP_HEADER_AUTH_USER_ID = "X-Auth-Id";

    @Override
    public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain) throws IOException, ServletException {
        HttpServletRequest httpServletRequest = (HttpServletRequest) request;
        String userAuthId = httpServletRequest.getHeader(HTTP_HEADER_AUTH_USER_ID);
        log.info("Incoming Request From {}", userAuthId);
        if (!StringUtils.isEmpty(userAuthId)) {
            ApiRequestContextHolder.getContext().setAuthId(userAuthId);
        }
        try {
            chain.doFilter(request, response);
        }finally {
            ApiRequestContextHolder.clearContext();
        }
    }
}

